-- gen595: 87 zone cambiate, 175 tessere
-- be71b7a3bab904ca33e9958ce31b2bc2 (741966) → 7fe37f874d86519e243ebab5686a6e2b (755150)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '7fe37f874d86519e243ebab5686a6e2b' as combacia
from kv_store where key like 'tmp:gen595:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen595:p%')
where key='app:jsx:src'
  and md5(value) = 'be71b7a3bab904ca33e9958ce31b2bc2'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen595:p%') = '7fe37f874d86519e243ebab5686a6e2b';

update kv_store set value = '{"len":755150,"ver":"gen-5.95"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '7fe37f874d86519e243ebab5686a6e2b';

delete from kv_store where key like 'tmp:gen595:p%';
